function prepareDevDir(platform: string): string {
  const devDir = join(SCAFFOLD_DIR, ".dev", platform);
  mkdirSync(devDir, { recursive: true });
  // .dev/<platform> sits inside the monorepo's own directory tree, so without its own
  // pnpm-workspace.yaml, pnpm walks up and finds the REAL one — `vp install` then treats it as
  // part of the 90-package monorepo workspace instead of an isolated project. An empty one here
  // stops that upward search. `blockExoticSubdeps` also has to live here (not .npmrc — pnpm only
  // reads auth/registry settings from .npmrc): the published `@pantoken/pantoken` meta package
  // devDependency every scaffold ships pulls in a git-hosted transitive dep pnpm's default policy
  // rejects as a subdependency.
  writeFileSync(join(devDir, "pnpm-workspace.yaml"), "packages: []\nblockExoticSubdeps: false\n");
  return devDir;
}", "newString": "/**
 * Extracts the root `pnpm-workspace.yaml`'s `catalog:` block verbatim (from `catalog:` up to the
 * next top-level key). Some scaffold templates (e.g. canvas-theme-editor's codemirror/tinymce
 * deps) ship `"catalog:"` version specifiers that only resolve against the monorepo's own catalog
 * — the isolated dev workspace needs a copy of it or `vp install` fails with
 * `ERR_PNPM_CATALOG_ENTRY_NOT_FOUND_FOR_SPEC`.
 */
function readRootCatalogBlock(): string {
  const rootWorkspaceYaml = readFileSync(join(REPO_ROOT, "pnpm-workspace.yaml"), "utf8");
  const lines = rootWorkspaceYaml.split("\n");
  const start = lines.findIndex((line) => line === "catalog:");
  if (start === -1) return "";
  const end = lines.findIndex((line, i) => i > start && /^[a-zA-Z]/.test(line));
  return `${lines.slice(start, end === -1 ? undefined : end).join("\n")}\n`;
}

/** Creates `.dev/<platform>` and isolates it from the monorepo's own pnpm workspace. */
function prepareDevDir(platform: string): string {
  const devDir = join(SCAFFOLD_DIR, ".dev", platform);
  mkdirSync(devDir, { recursive: true });
  // .dev/<platform> sits inside the monorepo's own directory tree, so without its own
  // pnpm-workspace.yaml, pnpm walks up and finds the REAL one — `vp install` then treats it as
  // part of the 90-package monorepo workspace instead of an isolated project. An empty one here
  // stops that upward search. `blockExoticSubdeps` also has to live here (not .npmrc — pnpm only
  // reads auth/registry settings from .npmrc): the published `@pantoken/pantoken` meta package
  // devDependency every scaffold ships pulls in a git-hosted transitive dep pnpm's default policy
  // rejects as a subdependency. The catalog block lets templates using `"catalog:"` specs resolve.
  writeFileSync(
    join(devDir, "pnpm-workspace.yaml"),
    `packages: []\nblockExoticSubdeps: false\n${readRootCatalogBlock()}`,
  );
  return devDir;
}"}

